/** Effective Paths firing rates, rapid-fire uptime and displayed game-speed scaling. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    realGameSpeed, bulletsPerSecond, rapidFireMultiplier
 * depends    src/mechanics/effective-paths/firing/types
 * used by    src/calculators/specs.generated, src/mechanics/effective-paths/firing/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
import type { RapidFireInput } from './types'

const KEYS: readonly number[] = [0, 2, 2.5, 3, 3.5, 4, 4.5, 5, 5.5, 6, 6.5, 7, 7.5, 8, 8.5, 9, 9.5, 10, 11, 12, 13, 14, 15]
const RATES: readonly number[] = [1, 0.96, 0.93, 0.9, 0.87, 0.84, 0.81, 0.79, 0.77, 0.75, 0.73, 0.71, 0.69, 0.67, 0.65, 0.63, 0.61, 0.58, 0.56, 0.54, 0.53, 0.52, 0.51]

/** `TTG_GAME_SPEED` — the sheet's exact scale behind a displayed game speed. */
export function realGameSpeed(displayedSpeed: number): number {
  const scale
    = displayedSpeed >= 5 ? 0.8
      : displayedSpeed >= 4.5 ? 0.82
        : displayedSpeed >= 4 ? 0.84
          : displayedSpeed >= 3.5 ? 0.88
            : displayedSpeed >= 3 ? 0.92
              : displayedSpeed >= 2.5 ? 0.95
                : displayedSpeed >= 2 ? 1
                  : 1.07
  return displayedSpeed * scale
}

/**
 * `BULLET_PER_SECOND` — bullets a second from attack speed.
 *
 * Exact transcription of the current sheet's piecewise firing curve. Below
 * sixteen it uses the next smaller lookup key, not interpolation.
 */
export function bulletsPerSecond(attackSpeed: number): number {
  if (!Number.isFinite(attackSpeed) || attackSpeed < 0) {
    throw new RangeError('attackSpeed must be finite and non-negative')
  }
  if (attackSpeed >= 42) return attackSpeed * 0.375
  if (attackSpeed >= 16) return attackSpeed * (0.505 - 0.005 * Math.floor(attackSpeed - 16))
  let index = KEYS.length - 1
  while (KEYS[index]! > attackSpeed) index--
  return attackSpeed * RATES[index]!
}

/**
 * `EPD_RAPIDFIRE` — the damage multiplier from rapid fire.
 *
 * Exact current sheet model: activation time, attack-speed bands and the frame
 * cap all affect uptime and benefit. attackSpeed is the raw stat, before
 * BULLET_PER_SECOND; the two quantities are not interchangeable.
 */
export function rapidFireMultiplier(input: RapidFireInput): number {
  const shots = bulletsPerSecond(input.attackSpeed)
  const cap = input.lightSpeedShots ? 1e300 : input.framesPerSecond / realGameSpeed(input.displayedGameSpeed)
  const base = Math.min(shots, cap)
  if (input.chance <= 0 || input.duration <= 0 || base <= 0) return 1
  const multiplier = input.attackSpeed < 2.3 ? 3.75 : input.attackSpeed < 4 ? 3.65 : input.attackSpeed < 8 ? 3.5 : 3.35
  const active = 0.9 * input.duration
  const uptime = active / (active + 0.75 + 1 / (input.chance * base))
  return ((1 - uptime) * base + uptime * Math.min(multiplier * shots, cap)) / base
}
